<script setup lang="ts">
import { ArrowRight, BookOpen, BrainCircuit, CheckCircle2, Edit3, History, Layers3, ListChecks, RefreshCw, Route, Search, Settings2, Sparkles, X } from 'lucide-vue-next'
import { computed, onMounted, reactive, ref } from 'vue'
import { api } from '../api'
import type { MessageLog, ThreadChannel, ThreadJob, ThreadProfile, ThreadRoutingDecisionRecord, ThreadRoutingRule } from '../types'

type Tab = 'overview' | 'library' | 'history' | 'advanced'
const activeTab = ref<Tab>('overview')
const rules = ref<ThreadRoutingRule[]>([])
const profiles = ref<ThreadProfile[]>([])
const decisions = ref<ThreadRoutingDecisionRecord[]>([])
const channels = ref<ThreadChannel[]>([])
const jobs = ref<ThreadJob[]>([])
const messages = ref<MessageLog[]>([])
const selectedProfile = ref<ThreadProfile | null>(null)
const loading = ref(false), saving = ref(false), error = ref(''), dialogOpen = ref(false)
const query = ref(''), sceneFilter = ref('')
const form = reactive({ sceneId: '', sceneName: '', enabled: false, reuseThreshold: 0.85, experienceThreshold: 0.55, timeWindowHours: 72, maxCandidates: 100, structuredWeight: 0.7, textWeight: 0.3 })

const enabledCount = computed(() => rules.value.filter(item => item.enabled).length)
const activeJobCount = computed(() => jobs.value.filter(item => item.status === 'queued' || item.status === 'processing').length)
const reusedCount = computed(() => decisions.value.filter(item => item.type === 'reused').length)
const experienceCount = computed(() => decisions.value.filter(item => item.type === 'experience').length)
const messageByLogId = computed(() => new Map(messages.value.map(item => [item.id, item])))
const ruleByScene = computed(() => new Map(rules.value.map(item => [item.sceneId, item])))
const filteredProfiles = computed(() => {
  const needle = query.value.trim().toLowerCase()
  return profiles.value.filter(item => (!sceneFilter.value || item.sceneId === sceneFilter.value) && (!needle || [item.title, item.normalizedText, item.experienceSummary, ...Object.values(item.fields)].join(' ').toLowerCase().includes(needle)))
})

const load = async () => {
  loading.value = true; error.value = ''
  try {
    const [routingRules, threadProfiles, routingDecisions, threadChannels, threadJobs, logs] = await Promise.all([api.threadRoutingRules(), api.threadProfiles(200), api.threadRoutingDecisions(100), api.threadChannels(), api.threadJobs(), api.messageLogs({ limit: 200 })])
    rules.value = routingRules; profiles.value = threadProfiles; decisions.value = routingDecisions; channels.value = threadChannels; jobs.value = threadJobs; messages.value = logs.items
  } catch (value) { error.value = value instanceof Error ? value.message : '读取失败' }
  finally { loading.value = false }
}
onMounted(load)
const edit = (rule: ThreadRoutingRule) => { Object.assign(form, rule); dialogOpen.value = true }
const save = async () => {
  saving.value = true; error.value = ''
  try {
    await api.saveThreadRoutingRule(form.sceneId, { enabled: form.enabled, reuseThreshold: form.reuseThreshold, experienceThreshold: form.experienceThreshold, timeWindowHours: form.timeWindowHours, maxCandidates: form.maxCandidates, structuredWeight: form.structuredWeight, textWeight: form.textWeight })
    dialogOpen.value = false; await load()
  } catch (value) { error.value = value instanceof Error ? value.message : '保存失败' }
  finally { saving.value = false }
}
const formatTime = (value: string) => value ? new Intl.DateTimeFormat('zh-CN', { dateStyle: 'short', timeStyle: 'short', hour12: false }).format(new Date(value)) : '—'
const percent = (value: number) => `${Math.round(value * 100)}%`
const thresholdColumns = (item: ThreadRoutingRule) => {
  const experience = Math.max(0.01, item.experienceThreshold)
  const reuse = Math.max(0.01, item.reuseThreshold - item.experienceThreshold)
  const newWork = Math.max(0.01, 1 - item.reuseThreshold)
  return `${experience}fr ${reuse}fr ${newWork}fr`
}
const profileTitle = (item: ThreadProfile) => item.title?.replace(/\s+/gu, ' ').trim().slice(0, 90) || '未命名经验'
const summary = (value: string, length = 160) => value?.replace(/\s+/gu, ' ').trim().slice(0, length) || '暂时没有可展示的结论摘要。'
const sceneName = (sceneId: string) => ruleByScene.value.get(sceneId)?.sceneName || '未知场景'
const fieldEntries = (item: ThreadProfile) => Object.entries(item.fields).filter(([, value]) => value).slice(0, 6)
const messageExcerpt = (logId: string) => summary(messageByLogId.value.get(logId)?.inboundContent || '', 110)
const typeLabel = (value: ThreadRoutingDecisionRecord['type']) => ({ fixed: '继续当前会话', new: '全新处理', reused: '复用历史会话', experience: '引用历史经验' }[value])
const typeClass = (value: ThreadRoutingDecisionRecord['type']) => value === 'reused' ? 'green' : value === 'experience' ? '' : 'gray'
const jobLabel = (value: ThreadJob['status']) => ({ queued: '排队中', processing: '执行中', completed: '已完成', failed: '失败' }[value])
const jobClass = (value: ThreadJob['status']) => value === 'completed' ? 'green' : value === 'failed' ? 'red' : 'gray'
const tabs: Array<{ key: Tab; label: string; icon: typeof Sparkles }> = [
  { key: 'overview', label: '概览', icon: Sparkles }, { key: 'library', label: '经验库', icon: BookOpen }, { key: 'history', label: '复用记录', icon: History }, { key: 'advanced', label: '高级信息', icon: Settings2 },
]
</script>

<template>
  <div class="page reuse-page">
    <header class="page-header"><div><p class="eyebrow">Experience reuse</p><h1>相似问题复用</h1><p class="page-description">系统从已完成的问题中沉淀经验。新消息到来时，判断是继续历史会话、引用已有经验，还是作为全新问题处理。</p></div><button class="ghost-button" :disabled="loading" @click="load"><RefreshCw :size="16" :class="{ spinning: loading }" />刷新</button></header>
    <nav class="reuse-tabs" aria-label="相似问题复用视图"><button v-for="tab in tabs" :key="tab.key" :class="{ active: activeTab === tab.key }" @click="activeTab = tab.key"><component :is="tab.icon" :size="16" />{{ tab.label }}<span v-if="tab.key === 'library'">{{ profiles.length }}</span><span v-if="tab.key === 'advanced' && activeJobCount">{{ activeJobCount }}</span></button></nav>
    <div v-if="error" class="error-banner" role="alert">{{ error }}</div>

    <template v-if="activeTab === 'overview'">
      <section class="reuse-summary">
        <article><BookOpen :size="18" /><div><strong>{{ profiles.length }}</strong><span>条可用经验</span></div><small>已完成问题沉淀出的特征和结论</small></article>
        <article><Sparkles :size="18" /><div><strong>{{ reusedCount }}</strong><span>次直接复用</span></div><small>相似度足够高，继续历史会话</small></article>
        <article><BrainCircuit :size="18" /><div><strong>{{ experienceCount }}</strong><span>次引用经验</span></div><small>带着历史结论重新调查</small></article>
        <article><Route :size="18" /><div><strong>{{ enabledCount }}/{{ rules.length }}</strong><span>个场景已启用</span></div><small>只在同 Bot、工作区和场景内比较</small></article>
      </section>

      <section class="explain-panel">
        <div class="explain-copy"><p class="eyebrow">How it works</p><h2>一条新消息会走向哪里？</h2><p>系统先提取服务、事件、告警规则等稳定特征，再结合文本内容和最近处理时间计算相似度。</p></div>
        <div class="outcome-flow"><div><span class="flow-dot fresh" /><strong>低于经验阈值</strong><small>作为全新问题处理</small></div><ArrowRight :size="18" /><div><span class="flow-dot reference" /><strong>达到经验阈值</strong><small>引用历史结论，重新验证</small></div><ArrowRight :size="18" /><div><span class="flow-dot reuse" /><strong>达到复用阈值</strong><small>继续同一个 Codex 会话</small></div></div>
      </section>

      <section class="overview-grid">
        <article class="panel"><div class="panel-header"><div><h2><History :size="17" />最近判断</h2><p class="panel-description">系统刚刚如何处理相似问题。</p></div><button class="text-button" @click="activeTab = 'history'">查看全部<ArrowRight :size="14" /></button></div>
          <div v-if="!decisions.length" class="empty"><History :size="30" /><strong>还没有判断记录</strong></div>
          <div v-else class="decision-list"><article v-for="item in decisions.slice(0, 6)" :key="item.logId"><div class="decision-top"><span class="badge" :class="typeClass(item.type)">{{ typeLabel(item.type) }}</span><time>{{ formatTime(item.receivedAt) }}</time></div><strong>{{ messageExcerpt(item.logId) }}</strong><p>{{ item.reason || '当前会话已有固定绑定。' }}</p><div class="decision-meta"><span>{{ item.sceneName }}</span><span v-if="item.score">匹配度 {{ percent(item.score) }}</span></div></article></div>
        </article>
        <article class="panel"><div class="panel-header"><div><h2><Settings2 :size="17" />场景策略</h2><p class="panel-description">用自然语言查看每个场景怎样复用经验。</p></div></div>
          <div class="rule-list"><article v-for="item in rules" :key="item.sceneId"><div class="rule-title"><div><strong>{{ item.sceneName }}</strong><span>{{ item.botName }} · {{ item.workspaceName }}</span></div><span class="badge" :class="item.enabled ? 'green' : 'gray'">{{ item.enabled ? '已启用' : '未启用' }}</span></div><p v-if="item.enabled">搜索最近 {{ item.timeWindowHours }} 小时的最多 {{ item.maxCandidates }} 条经验。达到 {{ percent(item.reuseThreshold) }} 时继续历史会话；达到 {{ percent(item.experienceThreshold) }} 时引用历史经验。</p><p v-else>当前不会主动匹配历史经验，会为新会话建立独立处理上下文。</p><div class="threshold" :style="{ gridTemplateColumns: thresholdColumns(item) }"><span class="new-zone">全新处理</span><span class="experience-zone">引用经验</span><span class="reuse-zone">继续会话</span><i :style="{ left: percent(item.experienceThreshold) }" /><i :style="{ left: percent(item.reuseThreshold) }" /></div><footer><span>{{ item.profileCount }} 条经验</span><button class="ghost-button compact" @click="edit(item)"><Edit3 :size="13" />配置</button></footer></article></div>
        </article>
      </section>
    </template>

    <template v-else-if="activeTab === 'library'">
      <section class="library-toolbar"><div><h2>经验库</h2><p>每条经验都包含识别特征、历史结论和对应的 Codex 会话。</p></div><div class="library-filters"><select v-model="sceneFilter" aria-label="按场景筛选"><option value="">全部场景</option><option v-for="item in rules" :key="item.sceneId" :value="item.sceneId">{{ item.sceneName }}</option></select><div class="filter-search"><Search :size="15" /><input v-model.trim="query" placeholder="搜索标题、特征或结论…" /></div></div></section>
      <div v-if="!filteredProfiles.length" class="panel empty"><BookOpen :size="32" /><strong>没有匹配的经验</strong><span>已完成的场景消息会自动沉淀为经验。</span></div>
      <section v-else class="experience-grid"><button v-for="item in filteredProfiles" :key="`${item.coreThreadId}:${item.sceneId}`" class="experience-card" @click="selectedProfile = item"><div class="experience-head"><span class="badge">{{ sceneName(item.sceneId) }}</span><time>{{ formatTime(item.lastActiveAt) }}</time></div><h3>{{ profileTitle(item) }}</h3><div class="feature-list"><span v-for="([name, value]) in fieldEntries(item)" :key="name"><small>{{ name }}</small>{{ value }}</span><span v-if="!fieldEntries(item).length" class="muted">暂未提取稳定特征</span></div><p>{{ summary(item.experienceSummary) }}</p><footer><span>{{ item.messageCount }} 条历史消息</span><span>查看详情<ArrowRight :size="13" /></span></footer></button></section>
    </template>

    <template v-else-if="activeTab === 'history'">
      <section class="section-intro"><div><h2>复用记录</h2><p>查看每条消息为什么复用、引用经验或新建处理。</p></div><span class="badge gray">最近 {{ decisions.length }} 条</span></section>
      <section class="panel"><div v-if="!decisions.length" class="empty"><History :size="32" /><strong>还没有复用记录</strong></div><div v-else class="history-list"><article v-for="item in decisions" :key="item.logId"><div class="history-message"><time>{{ formatTime(item.receivedAt) }}</time><strong>{{ messageExcerpt(item.logId) }}</strong><span>{{ item.sceneName }}</span></div><div class="history-outcome"><span class="badge" :class="typeClass(item.type)">{{ typeLabel(item.type) }}</span><strong v-if="item.score">{{ percent(item.score) }} 匹配</strong><p>{{ item.reason || '当前会话已有固定绑定。' }}</p></div><code class="history-thread">{{ item.coreThreadId || item.matchedThreadId || '尚未创建 Thread' }}</code></article></div></section>
    </template>

    <template v-else>
      <section class="advanced-note"><Settings2 :size="19" /><div><strong>高级信息</strong><p>这里保留 Thread Channel、Codex Thread 和持久队列，主要用于运行排查。</p></div></section>
      <section class="panel"><div class="panel-header"><div><h2><Layers3 :size="17" />Thread Channels</h2><p class="panel-description">多个群或话题可以共享一个 Channel 和 Codex Thread。</p></div><span class="badge gray">{{ channels.length }} 个</span></div><div class="table-wrap"><table><thead><tr><th>最后活跃</th><th>Bot</th><th>会话数</th><th>任务</th><th>Channel / Thread</th></tr></thead><tbody><tr v-for="item in channels" :key="item.id"><td>{{ formatTime(item.updatedAt) }}</td><td>{{ item.botName }}</td><td>{{ item.bindingCount }}</td><td>{{ item.processingJobs ? `执行 ${item.processingJobs}` : item.queuedJobs ? `排队 ${item.queuedJobs}` : '空闲' }}</td><td><code class="thread-id">{{ item.id }}</code><div class="entity-subtitle mono">{{ item.coreThreadId || '尚未创建' }}</div></td></tr></tbody></table></div></section>
      <section class="panel advanced-panel"><div class="panel-header"><div><h2><ListChecks :size="17" />任务队列</h2><p class="panel-description">同一个 Channel 的消息会按顺序执行。</p></div><span class="badge gray">最近 {{ jobs.length }} 条</span></div><div v-if="!jobs.length" class="empty"><CheckCircle2 :size="30" /><strong>当前没有队列记录</strong></div><div v-else class="table-wrap"><table><thead><tr><th>创建时间</th><th>状态</th><th>消息</th><th>Channel</th></tr></thead><tbody><tr v-for="item in jobs" :key="item.id"><td>{{ formatTime(item.createdAt) }}</td><td><span class="badge" :class="jobClass(item.status)">{{ jobLabel(item.status) }}</span></td><td><code>{{ item.messageId }}</code><div v-if="item.error" class="entity-subtitle">{{ item.error }}</div></td><td><code class="thread-id">{{ item.threadChannelId }}</code></td></tr></tbody></table></div></section>
    </template>

    <div v-if="selectedProfile" class="dialog-backdrop" @mousedown.self="selectedProfile = null"><section class="dialog large"><header class="dialog-header"><div><h2>{{ profileTitle(selectedProfile) }}</h2><p>{{ sceneName(selectedProfile.sceneId) }} · 最近使用 {{ formatTime(selectedProfile.lastActiveAt) }}</p></div><button class="icon-button" aria-label="关闭" @click="selectedProfile = null"><X :size="19" /></button></header><div class="dialog-body"><div class="detail-grid"><div><span>历史消息</span><strong>{{ selectedProfile.messageCount }} 条</strong></div><div><span>所属场景</span><strong>{{ sceneName(selectedProfile.sceneId) }}</strong></div><div><span>最后更新</span><strong>{{ formatTime(selectedProfile.updatedAt) }}</strong></div></div><div class="record-content"><h3>识别特征</h3><div class="profile-fields"><div v-for="([name, value]) in Object.entries(selectedProfile.fields)" :key="name"><span>{{ name }}</span><strong>{{ value }}</strong></div><p v-if="!Object.keys(selectedProfile.fields).length" class="muted">暂未提取稳定特征。</p></div></div><div class="record-content"><h3>最近结论</h3><pre>{{ selectedProfile.experienceSummary || '暂时没有可展示的结论摘要。' }}</pre></div><details class="record-content"><summary>技术信息</summary><div class="record-meta mono">channel: {{ selectedProfile.threadChannelId }}<br />thread: {{ selectedProfile.coreThreadId }}<br />last log: {{ selectedProfile.lastMessageLogId }}</div></details></div></section></div>

    <div v-if="dialogOpen" class="dialog-backdrop" @mousedown.self="dialogOpen = false"><form class="dialog large" @submit.prevent="save"><header class="dialog-header"><div><h2>配置经验复用</h2><p>{{ form.sceneName }}</p></div><button type="button" class="icon-button" aria-label="关闭" @click="dialogOpen = false"><X :size="19" /></button></header><div class="dialog-body"><label class="check-card"><input v-model="form.enabled" type="checkbox" /><span><strong>启用相似问题复用</strong><small>只在同一 Bot、工作区和场景内检索。</small></span></label><div class="field-grid"><div class="field"><label>继续历史会话阈值</label><input v-model.number="form.reuseThreshold" type="number" min="0" max="1" step="0.01" /><small>达到后继续同一个 Codex 会话。</small></div><div class="field"><label>引用经验阈值</label><input v-model.number="form.experienceThreshold" type="number" min="0" max="1" step="0.01" /><small>达到后新建会话，并带入历史结论。</small></div></div><div class="field-grid"><div class="field"><label>搜索最近多少小时</label><input v-model.number="form.timeWindowHours" type="number" min="1" max="8760" /></div><div class="field"><label>最多比较多少条经验</label><input v-model.number="form.maxCandidates" type="number" min="10" max="1000" /></div></div><details class="advanced-config"><summary>高级匹配权重</summary><div class="field-grid"><div class="field"><label>结构化特征权重</label><input v-model.number="form.structuredWeight" type="number" min="0" max="1" step="0.05" /></div><div class="field"><label>文本特征权重</label><input v-model.number="form.textWeight" type="number" min="0" max="1" step="0.05" /></div></div></details><div v-if="error" class="error-banner" role="alert">{{ error }}</div></div><footer class="dialog-actions"><button type="button" class="ghost-button" @click="dialogOpen = false">取消</button><button class="button" :disabled="saving">{{ saving ? '保存中…' : '保存规则' }}</button></footer></form></div>
  </div>
</template>

<style scoped>
.reuse-page{max-width:1440px}.reuse-tabs{display:flex;gap:5px;margin:-10px 0 18px;padding:5px;background:var(--surface);border:1px solid var(--border);border-radius:13px}.reuse-tabs button{min-height:40px;display:inline-flex;align-items:center;gap:7px;padding:0 14px;color:var(--muted);background:transparent;border:0;border-radius:9px;font-size:12px;font-weight:650}.reuse-tabs button:hover{color:var(--text);background:var(--surface-raised)}.reuse-tabs button.active{color:var(--text);background:var(--primary-soft);box-shadow:inset 0 0 0 1px var(--primary-border)}.reuse-tabs button span{min-width:18px;padding:2px 5px;background:var(--surface-soft);border-radius:999px;font-size:9px}.reuse-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}.reuse-summary article{display:grid;grid-template-columns:auto 1fr;gap:5px 11px;padding:18px;background:var(--surface);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow-soft)}.reuse-summary svg{grid-row:1/3;color:var(--primary)}.reuse-summary strong{margin-right:7px;font:700 22px/1 ui-monospace,SFMono-Regular,Menlo,monospace}.reuse-summary span{color:var(--text-soft);font-size:12px;font-weight:650}.reuse-summary small{grid-column:2;color:var(--muted);font-size:10px;line-height:1.45}.explain-panel{display:grid;grid-template-columns:minmax(260px,.65fr) minmax(0,1.35fr);gap:26px;align-items:center;margin-bottom:16px;padding:24px 26px;background:linear-gradient(120deg,var(--primary-soft),transparent 48%),var(--surface);border:1px solid var(--border);border-radius:16px}.explain-copy h2{margin:0;font-size:20px}.explain-copy p:last-child{margin:8px 0 0;color:var(--muted);font-size:12px;line-height:1.6}.outcome-flow{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:10px}.outcome-flow>div{padding:14px;background:var(--surface-raised);border:1px solid var(--border);border-radius:11px}.outcome-flow>svg{color:var(--muted)}.outcome-flow strong,.outcome-flow small{display:block}.outcome-flow strong{margin:8px 0 5px;font-size:11px}.outcome-flow small{color:var(--muted);font-size:10px;line-height:1.45}.flow-dot{width:8px;height:8px;display:block;border-radius:50%}.flow-dot.fresh{background:var(--muted)}.flow-dot.reference{background:var(--primary)}.flow-dot.reuse{background:var(--green)}.overview-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(390px,.8fr);gap:16px}.text-button{display:inline-flex;align-items:center;gap:5px;color:var(--primary);background:transparent;border:0;font-size:11px;font-weight:700}.decision-list{display:grid}.decision-list article{padding:16px 20px;border-top:1px solid var(--border)}.decision-list article:first-child{border-top:0}.decision-top,.decision-meta,.rule-title,.rule-title>div,.rule-list footer,.experience-head,.experience-card footer,.section-intro{display:flex;align-items:center;justify-content:space-between;gap:12px}.decision-top time,.experience-head time{color:var(--muted);font-size:10px}.decision-list article>strong{display:block;margin:10px 0 6px;font-size:12px;line-height:1.5}.decision-list p{margin:0;color:var(--muted);font-size:10px;line-height:1.5}.decision-meta{justify-content:flex-start;margin-top:9px;color:var(--muted);font-size:10px}.rule-list{display:grid}.rule-list article{padding:17px 20px;border-top:1px solid var(--border)}.rule-list article:first-child{border-top:0}.rule-title>div{display:grid;justify-items:start;gap:4px}.rule-title strong{font-size:12px}.rule-title>div span{color:var(--muted);font-size:10px}.rule-list p{margin:11px 0;color:var(--muted);font-size:10px;line-height:1.55}.threshold{position:relative;height:24px;display:grid;grid-template-columns:55fr 30fr 15fr;overflow:hidden;margin-bottom:11px;border:1px solid var(--border);border-radius:7px}.threshold span{display:grid;place-items:center;font-size:8px}.new-zone{color:var(--muted);background:var(--surface-raised)}.experience-zone{color:#aeb5ff;background:var(--primary-soft)}.reuse-zone